import {bindPreceptBattle} from './precept-battle.js';
import {approvedGatekeeperChallenges} from './gatekeeper-approved.js';
import {gatekeeperBattle,settleGatekeeper} from './gatekeeper-chains.js';

function startGatekeeperChain(){
 const battle=gatekeeperBattle(run,approvedGatekeeperChallenges);
 if(!battle)return false;
 const owner=run,level=run.level;
 const opened=arena.startGatekeeper({
  battle,
  scene:()=>`<div class="game-scene precept-arena boss-scene adventure-arena" aria-label="Gatekeeper arena">${landscape(Math.min(environments.length-1,environments.filter(e=>owner.completed>=e.unlock).length-1))}${symbolicGate({broken:0,total:10})}<div class="scene-status"><span>⚔ GATEKEEPER CHALLENGE <b>${esc(opponentFor(level).name)}</b></span>${judah(owner.completed,'ready',false)}${romanSoldier()}<span class="combat-sparks" aria-hidden="true"></span></div></div>`,
  onExit:()=>setView('title'),
  onResult:result=>{
   if(run!==owner||!settleGatekeeper(run,level,result))return setView('title');
   persist();
   setView('game');
   void audio.effect(result.phase==='victory'?'gateOpen':'gameover');
   $('#screen-title')?.focus();
  }
 });
 if(opened){stopClock();view='gatekeeper-chain';paused=false;}
 return opened;
}
